const item = $input.first();
const binary = item.binary ?? {};
const files = Object.keys(binary).map((field) => {
  const file = binary[field];
  return {
    field,
    fileName: file.fileName ?? null,
    mimeType: file.mimeType ?? null,
    fileSize: file.fileSize ?? null,
  };
});

return [{
  json: {
    status: "accepted",
    stage: "smoke",
    analysis_id: `smoke-${Date.now()}`,
    pages: item.json?.pages || null,
    files,
    message: "Frontend -> n8n работает. Реальный анализ подключается на следующем этапе."
  }
}];
